import{_ as n,o as i,c as r,a3 as t}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Suche","description":"Einträge in ApptiveGrid finden — über die Suche und über Filter.","frontmatter":{"title":"Suche","description":"Einträge in ApptiveGrid finden — über die Suche und über Filter."},"headers":[],"relativePath":"grids/suche.md","filePath":"grids/suche.md","lastUpdated":1786087702000}'),a={name:"grids/suche.md"};function s(h,e,d,c,l,u){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="suche" tabindex="-1">Suche <a class="header-anchor" href="#suche" aria-label="Permalink to &quot;Suche&quot;">​</a></h1><h2 id="suche-1" tabindex="-1">Suche <a class="header-anchor" href="#suche-1" aria-label="Permalink to &quot;Suche&quot;">​</a></h2><p>Über <strong>Suche</strong> durchsuchen Sie Einträge. Das Eingabefeld heißt <em>Suche nach Einträgen</em>.</p><p>Bei vielen Treffern lädt <strong>Mehr laden ({items} von {totalItems})</strong> weitere nach. Ohne Treffer erscheint <em>Keine Ergebnisse gefunden.</em>, bei einem Problem <em>Fehler beim Suchen</em>.</p><h2 id="suchen-oder-filtern" tabindex="-1">Suchen oder filtern? <a class="header-anchor" href="#suchen-oder-filtern" aria-label="Permalink to &quot;Suchen oder filtern?&quot;">​</a></h2><p>Beides führt zu Einträgen, aber sie leisten Unterschiedliches:</p><table tabindex="0"><thead><tr><th></th><th>Suche</th><th><a href="/ansichten/filtern-sortieren-gruppieren">Filter</a></th></tr></thead><tbody><tr><td>Zweck</td><td>Etwas Bestimmtes finden</td><td>Eine Teilmenge dauerhaft zeigen</td></tr><tr><td>Dauer</td><td>Einmalig</td><td>Teil der Ansicht</td></tr><tr><td>Gilt für</td><td>Sie</td><td>alle, die die Ansicht sehen</td></tr><tr><td>Genauigkeit</td><td>Freitext</td><td>Bedingung je Feld</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Faustregel</p><p><strong>Suche</strong>, wenn Sie einen konkreten Eintrag suchen und dessen Namen kennen. <strong>Filter</strong>, wenn Sie regelmäßig mit derselben Teilmenge arbeiten.</p><p>Brauchen Sie eine Teilmenge nur kurz, ohne die Ansicht für andere zu verändern, nehmen Sie den temporären Filter (<em>Einträge suchen und filtern (temporär)</em>).</p></div><h2 id="innerhalb-einer-ansicht-suchen" tabindex="-1">Innerhalb einer Ansicht suchen <a class="header-anchor" href="#innerhalb-einer-ansicht-suchen" aria-label="Permalink to &quot;Innerhalb einer Ansicht suchen&quot;">​</a></h2><p>Zusätzlich zur allgemeinen Suche hat die Werkzeugleiste einer Ansicht eine eigene Suchfunktion, die nur die Einträge dieser Ansicht durchsucht — also innerhalb der bereits gefilterten Menge.</p><div class="tip custom-block"><p class="custom-block-title">Zweistufig vorgehen</p><p>Erst über den Filter grob eingrenzen, dann in der Ansicht suchen. Bei großen Grids ist das schneller und präziser, als eine Freitextsuche über alles laufen zu lassen.</p></div><h2 id="suche-in-portalen" tabindex="-1">Suche in Portalen <a class="header-anchor" href="#suche-in-portalen" aria-label="Permalink to &quot;Suche in Portalen&quot;">​</a></h2><p>Bei einer in eine <a href="/seiten/was-sind-seiten">Seite</a> eingebetteten Ansicht steuern Sie über die Blockeinstellung <strong>Suche anzeigen</strong>, ob Besucher suchen dürfen. Ebenso <strong>Filter anzeigen</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Für Portale mit vielen Einträgen einschalten</p><p>Ein Portal mit einigen hundert Einträgen ist ohne Suchfeld für Besucher kaum benutzbar. Beide Optionen kosten nichts und ändern nichts an den Zugriffsrechten — sie erlauben nur, die ohnehin sichtbaren Daten zu durchsuchen.</p></div><p>→ <a href="/seiten/auswertungen">Ansichten und Auswertungen einbetten</a></p><h2 id="einen-eintrag-uber-sein-feld-finden" tabindex="-1">Einen Eintrag über sein Feld finden <a class="header-anchor" href="#einen-eintrag-uber-sein-feld-finden" aria-label="Permalink to &quot;Einen Eintrag über sein Feld finden&quot;">​</a></h2><p>Bei Feldern vom Typ <strong>Eintrag verknüpfen</strong> und <strong>Mehrere Einträge verknüpfen</strong> gibt es eine eigene Suche im Auswahldialog. Ohne Treffer erscheint <em>Kein passender Eintrag gefunden.</em></p><div class="warning custom-block"><p class="custom-block-title">Die Zielansicht kann Treffer verhindern</p><p>Der Auswahldialog zeigt nur Einträge aus der <strong>Ansicht</strong>, die bei der Verknüpfung hinterlegt ist. Ist diese gefiltert, fehlen Einträge, die es im Grid durchaus gibt.</p><p>Wenn ein bekannter Eintrag nicht auffindbar ist, prüfen Sie zuerst den Filter der Zielansicht. → <a href="/grids/verknuepfungen">Grids verknüpfen</a></p></div><h2 id="spaces-durchsuchen" tabindex="-1">Spaces durchsuchen <a class="header-anchor" href="#spaces-durchsuchen" aria-label="Permalink to &quot;Spaces durchsuchen&quot;">​</a></h2><p>Die Space-Übersicht hat eine eigene Suche (<em>Space suchen…</em>), die Space-Namen durchsucht — nicht deren Inhalte.</p><p>→ <a href="/spaces/space-anlegen">Space anlegen</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li><li><a href="/grids/eintraege">Einträge anlegen und bearbeiten</a></li><li><a href="/grids/verknuepfungen">Grids verknüpfen</a></li></ul>',23)])])}const p=n(a,[["render",s]]);export{g as __pageData,p as default};
